import{at as e,it as t,n,vt as r}from"./chunks/framework.DdRMjwGS.js";var i=JSON.parse(`{"title":"代码生成","description":"","frontmatter":{},"headers":[],"relativePath":"backend/code-generation.md","filePath":"backend/code-generation.md","lastUpdated":1794152868000}`),a={name:`backend/code-generation.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="代码生成" tabindex="-1">代码生成 <a class="header-anchor" href="#代码生成" aria-label="Permalink to “代码生成”">​</a></h1><p>本页说明代码生成的数据源、表与列配置、模板与生成的代码、交付、零代码运行时和退出验证，适用于用它生成业务包的开发者与维护模板的人。</p><p>CodeGeneration 是 Tier 3 的可选模块（<code>BasicApp:Modules:CodeGeneration:Enabled</code>，缺省开），只在平台一侧：管理外部数据源，按库表结构导入表与列配置，用 Scriban 模板生成一个后端包与前端模块，记生成历史，另有零代码只读运行时。</p><h2 id="页面与权限" tabindex="-1">页面与权限 <a class="header-anchor" href="#页面与权限" aria-label="Permalink to “页面与权限”">​</a></h2><p>页面 <code>codegeneration.code-gen</code>（路由 <code>/codegeneration/code-gen</code>，在「系统管理 › 在线开发」目录下，菜单按 <code>codegeneration.codegen-tables.read</code> 下发），一页四签：表配置、数据源、模板、生成历史，各页签按自己资源的读权限显示。</p><p>权限码只在平台一侧，资源段与操作一致：</p><table tabindex="0"><thead><tr><th>资源</th><th>权限码</th></tr></thead><tbody><tr><td>数据源 <code>codegen-datasources</code></td><td><code>read</code>、<code>create</code>、<code>update</code>（修改、启停、测试连接）、<code>delete</code></td></tr><tr><td>表配置 <code>codegen-tables</code></td><td><code>read</code>（也是页面读权限，含列出库表与预览）、<code>update</code>（修改、启停）、<code>delete</code>、<code>import</code>（导入、同步结构）、<code>execute</code>（生成代码）</td></tr><tr><td>列配置 <code>codegen-table-columns</code></td><td><code>read</code>、<code>update</code>（整体保存）</td></tr><tr><td>模板 <code>codegen-templates</code></td><td><code>read</code>（查看、检查语法）、<code>create</code>、<code>update</code>（修改、启停）、<code>delete</code></td></tr><tr><td>生成历史 <code>codegen-histories</code></td><td><code>read</code>（查看、下载产物包）</td></tr><tr><td>零代码运行时 <code>codegen-runtime</code></td><td><code>read</code>（查看表结构与数据）</td></tr></tbody></table><p>完整码是 <code>codegeneration.&lt;资源&gt;.&lt;动作&gt;</code>，如 <code>codegeneration.codegen-tables.execute</code>；写操作进操作日志。字段安全登记了数据源、表配置与模板。</p><h2 id="数据源" tabindex="-1">数据源 <a class="header-anchor" href="#数据源" aria-label="Permalink to “数据源”">​</a></h2><p>外部库的连接信息，导入表结构与零代码运行时经它连库；表配置的数据源为空即主库。</p><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><code>codegen-datasources.list</code></td><td>分页；关键字匹配名称、描述、主机与库名，数据库类型与状态可多选</td></tr><tr><td><code>codegen-datasources.options</code></td><td>全部数据源（含停用的），给下拉用</td></tr><tr><td><code>codegen-datasources.get</code></td><td>详情；口令与连接串不回显，只说有没有显式连接串</td></tr><tr><td><code>codegen-datasources.create</code> / <code>update</code></td><td>名称唯一（<code>CODEGENERATION_CONFLICT_001</code>）；口令与显式连接串加密存储，编辑时留空即不改，但改了库类型、主机或端口必须重新填写口令（<code>CODEGENERATION_VALIDATION_014</code>）；设为缺省时其余的取消缺省</td></tr><tr><td><code>codegen-datasources.set-status</code></td><td>启停；停用的不能用于读库结构与查询（<code>CODEGENERATION_CONFLICT_003</code>）</td></tr><tr><td><code>codegen-datasources.delete</code></td><td>批量；仍被表配置引用的逐项拒绝（<code>CODEGENERATION_CONFLICT_002</code>）</td></tr><tr><td><code>codegen-datasources.test-connection</code></td><td>按当前设置临时连一次（停用的也能测），记下时间、结果与说明；连不上写在结果里，不是失败的调用</td></tr></tbody></table><ul><li>支持 MySQL、SQL Server、PostgreSQL、Oracle、SQLite。显式连接串优先，没有就按主机、端口、库名、账号拼出，附加参数追加在拼出的连接串之后；SQLite 的库名是库文件路径。</li><li>SQLite 数据源要打开 <code>BasicApp:CodeGeneration:AllowSqliteDataSource</code>（缺省关，Development 开），否则 <code>CODEGENERATION_VALIDATION_013</code>：它的地址是服务器上的文件路径，开放等于能读进程够得着的任意数据库文件。</li><li>连接串里的主机过出站地址策略（<code>XiHan:Security:Outbound</code>），缺省只能连公网；内网数据库要在那里放行，否则 <code>CODEGENERATION_VALIDATION_012</code>，见<a href="./../configuration#xihan-security-outbound">配置参考</a>。</li><li>口令与连接串经 <code>ISecretProtector</code>（数据保护）加密，解不开即 503 <code>CODEGENERATION_UNAVAILABLE_001</code>，要重新填写（数据保护密钥变了时会这样）。</li><li>连接经框架的运行时数据源（<code>DataSourceRegistry</code>）：首次使用时按定义登记一个连接（名字 <code>codegen-&lt;ID&gt;</code>，每个数据源一条健康项 <code>persistence.datasource.codegen-&lt;ID&gt;</code>），修改、启停与删除之后注销，下次使用按新设置重建。登记数上限是 <code>XiHan:Persistence:DataSources:MaxCount</code>（缺省 64）。连不上、连接串不合格式由框架报 <code>PERSISTENCE_*</code>，原样返回。</li></ul><h2 id="表配置与列配置" tabindex="-1">表配置与列配置 <a class="header-anchor" href="#表配置与列配置" aria-label="Permalink to “表配置与列配置”">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><code>codegen-tables.db-tables</code></td><td>分页列出主库或某个启用的数据源里的表；关键字匹配表名与注释，分表折叠成逻辑名，页码换算成跳过与取的条数交给框架</td></tr><tr><td><code>codegen-tables.import</code></td><td>导入一批表（1 到 100 张），按表隔离：读不到、已导入（<code>CODEGENERATION_CONFLICT_004</code>）、没有列（<code>CODEGENERATION_VALIDATION_002</code>）的各记一条失败</td></tr><tr><td><code>codegen-tables.sync-schema</code></td><td>按最新库结构同步：结构字段以库为准，推断字段没被人工改过才跟随新的推断，新列补进来、库里已删的列删掉列配置</td></tr><tr><td><code>codegen-tables.list</code> / <code>get</code> / <code>options</code> / <code>update</code> / <code>set-status</code> / <code>delete</code></td><td>表配置的增改删查；修改时值变了的被跟踪字段记为人工改过，表名不能改（<code>CODEGENERATION_VALIDATION_011</code>），生成模式不能是通用（<code>VALIDATION_003</code>），勾了导入须勾新建（<code>VALIDATION_004</code>）；删除连带列配置</td></tr><tr><td><code>codegen-table-columns.list</code> / <code>save</code></td><td>一张表的列配置；整体保存，任一列不过即整次不写，选项来源（字典、枚举、常量、关联表、关联树）只留它要的那个配置</td></tr></tbody></table><ul><li>读库结构用框架的 <code>ISchemaReader</code>（主库传空，外部库传数据源的连接定义），表名与列名照返回的原名，不自己转大小写。</li><li>类型按「库 + 类型名」映射：长度只给字符与二进制类型；Oracle 的 <code>NUMBER</code> 按精度与小数位分整数与定点数、<code>DATE</code> 带时分秒；SQL Server 的 <code>timestamp</code> 是行版本，按二进制；不认得的类型按字符串。<code>long</code> 在报文里是数字，TypeScript 是 <code>number</code>、控件是数字框。PostgreSQL、MySQL、SQL Server、Oracle 在真实库上实测（<code>CodeGenerationSchemaTests</code>，读 <code>XIHAN_TEST_POSTGRES</code> / <code>XIHAN_TEST_MYSQL</code> / <code>XIHAN_TEST_SQLSERVER</code> / <code>XIHAN_TEST_ORACLE</code>）。</li><li>推断：类名去掉表名前缀（<code>BasicApp:CodeGeneration:TablePrefixes</code>，逗号分隔的字符串，缺省 <code>sys_</code>，取最长的匹配）转 PascalCase，业务名取表注释；字符列按列名语义推控件（图片、文件、备注……），名称、编码、状态、类型、时间、日期类的列缺省可查询；有父级列与名称列即树表。实体基类的列（主键、租户、审计、软删与并发戳）不进表单与列表。</li><li>「沿用已有实体」：主库里已登记实体的表（框架的 <code>IEntityCatalog</code>），类名、命名空间、包名与属性名取实体，枚举属性推为枚举选项，生成目标缺省「加入已有包」。外部库的同名表不算。</li><li>数据库类型按来源取：主库取主库的连接，外部库取数据源记录。</li></ul><h2 id="模板与预览" tabindex="-1">模板与预览 <a class="header-anchor" href="#模板与预览" aria-label="Permalink to “模板与预览”">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><code>codegen-templates.list</code> / <code>get</code></td><td>分页（不带正文；分组、生成模式、写入方式、状态可筛选，关键字匹配编码、名称与描述）与详情（带正文与路径表达式）</td></tr><tr><td><code>codegen-templates.validate</code></td><td>只解析不渲染，返回带行列的语法错误；正文可能很长，走 POST</td></tr><tr><td><code>codegen-templates.create</code> / <code>update</code> / <code>set-status</code> / <code>delete</code></td><td>自有模板可增删改；编码唯一（<code>CODEGENERATION_CONFLICT_005</code>）、不含空白、建好后不能改；内置模板不能改、不能删（<code>CODEGENERATION_CONFLICT_006</code>），可以启停</td></tr><tr><td><code>codegen-tables.preview</code></td><td>按表配置渲染，返回全部文件，不打包、不记历史；配置检查不过 <code>CODEGENERATION_VALIDATION_007</code>，模板渲染失败或产物越出根目录 <code>VALIDATION_008</code>（带模板编码），没有可用模板 <code>VALIDATION_009</code></td></tr></tbody></table><ul><li>内置模板随程序版本走：包里带的 <code>Seeds/Templates/**/*.sbn</code> 由种子 <code>codegeneration.templates</code> 在每次执行 <code>seed</code> 时对齐到模板表（正文、名称、分组、生成模式、扩展名、路径表达式、写入方式与排序），启停归运维、不动；要定制就新建一份自有模板。</li><li>选模板：显式给了编码就用那几个，否则取启用的通用模板与表的生成模式的模板；按生成范围裁（分组含 <code>backend</code> / <code>frontend</code>）；目标是「加入已有包」时不出包级模板（分组 <code>*-package</code>）；沿用已有实体时不出实体。一份模板渲染出空白即不产出这个文件（按勾选的操作一份模板一个文件）。</li><li>渲染用 Scriban：变量以 PascalCase 原名注入（<code>{{ ClassName }}</code>、<code>{{ for col in Columns }}</code>），带转义过滤器（<code>cs_string</code>、<code>xml_doc</code>、<code>ts_string</code>、<code>html_attr</code>、<code>html_text</code>、<code>block_comment</code>、<code>html_comment</code>、<code>i18n_message</code>、<code>js_literal</code>、<code>select_options</code>）与 <code>kebab</code> / <code>snake</code> / <code>camel</code> / <code>sort_names</code>；不能引入别的文件，循环（10000 次）与递归（50 层）有上限。</li><li>生成前的检查不过即整次失败：模块名与命名空间要合规；表已有手写实体时类名要与它一致；系统字典列要是文本、有字典码；选了枚举的列要解析得到、C# 类型就是它；关联列要是 <code>Guid</code>，关联的表要在、显示列要是文本，关联树的目标要是配好父级列的树表；唯一列不能是布尔或二进制；树表的父级列要是 <code>Guid</code>、名称列要进列表；主从的明细表要配好主表与外键列；勾了状态切换要有一列启停枚举（有 <code>Active</code> 与 <code>Disabled</code> 成员）且进列表；新建实体时，属性名为 <code>Status</code>、没选枚举的整数列也可以，生成器在实体里出 <code>&lt;类&gt;Status</code>（<code>Active</code> 0、<code>Disabled</code> 1）。</li></ul><h3 id="生成的后端代码" tabindex="-1">生成的后端代码 <a class="header-anchor" href="#生成的后端代码" aria-label="Permalink to “生成的后端代码”">​</a></h3><p>一张表生成一个资源：资源名是类名的 kebab 复数（<code>SalesOrder</code> → <code>sales-orders</code>），操作 <code>&lt;资源&gt;.list / get / create / update / delete / set-status / tree / &lt;属性&gt;-options</code>，权限码 <code>&lt;包&gt;.&lt;资源&gt;.read / create / update / delete</code>（只在租户侧，写操作记审计），页面 <code>&lt;包&gt;.&lt;资源&gt;</code>（路由 <code>/&lt;包&gt;/&lt;资源&gt;</code>）。实体是租户库实体（<code>TenantScopedAuditedEntity</code>），表名或列名与按约定换算的不同时才写 <code>[SugarTable]</code> / <code>[SugarColumn]</code>，唯一列是部分唯一索引。</p><p>文件落在 <code>src/&lt;命名空间&gt;/</code> 下：</p><table tabindex="0"><thead><tr><th>文件</th><th>写入方式</th></tr></thead><tbody><tr><td><code>Domain/Entities/&lt;类&gt;.Generated.cs</code></td><td>每次覆盖</td></tr><tr><td><code>Domain/Entities/&lt;类&gt;.cs</code></td><td>只首次（partial，写计算属性与领域方法）</td></tr><tr><td><code>Operations/&lt;资源&gt;/&lt;类&gt;Contracts.Generated.cs</code></td><td>每次覆盖：响应、请求与映射</td></tr><tr><td><code>Operations/&lt;资源&gt;/&lt;类&gt;Contracts.cs</code></td><td>只首次（partial）</td></tr><tr><td><code>Operations/&lt;资源&gt;/&lt;动作&gt;.cs</code></td><td>只首次，按勾选的操作（<code>List&lt;资源&gt;</code>、<code>Get&lt;类&gt;</code>、<code>Create&lt;类&gt;</code> ……）；树表另有 <code>Get&lt;类&gt;Tree</code>，关联列另有 <code>&lt;类&gt;OptionOperations</code></td></tr><tr><td><code>Queries/&lt;类&gt;Queries.Generated.cs</code></td><td>每次覆盖：分页、筛选与排序的白名单（模糊查询进关键字，日期与创建时间按区间，选项列可多选）</td></tr><tr><td><code>Queries/&lt;类&gt;Queries.cs</code></td><td>只首次：<code>Customize</code> 里写缺省条件</td></tr><tr><td><code>Operations/&lt;资源&gt;/&lt;类&gt;PrintDataSource.Generated.cs</code></td><td>每次覆盖，勾了打印才有</td></tr></tbody></table><p>两种目标：</p><ul><li><strong>新建包</strong>另出包级文件（工程文件、Feature、Capabilities、Permissions、Pages、Errors、Messages、JsonContext、README，都只首次）与 <code>Localization/&lt;区域&gt;.json</code> 共 10 种区域。按 Tier 3 登记，只依赖 Contracts 与 Runtime（用到别的包的枚举或关联实体时另加引用）。</li><li><strong>加入已有包</strong>只出资源的文件，错误码序号留成 <code>NNN</code> 待填。</li></ul><p>两种目标都出 <code>_registration/&lt;资源&gt;.md</code>：新建包写明加进解决方案、宿主（<code>UseFeature</code>、OpenAPI 分组）与架构测试 Tier 表的行；加入已有包按文件列出要合入的权限码、页面、错误码、消息键、JSON 序列化类型、Feature 登记与 10 种区域的文案。操作 ID 已被别的包占用时在开头提示。</p><p>生成的文案：固定用语（「新建」「删除」「查看」……）按 10 种区域内置，表注释与列注释在 10 种区域里原样使用（不机器翻译），生成之后按需改写。业务名、表注释与列注释当名字用或拼进句子时去掉句末的标点，表配置里存的照原样。</p><h3 id="生成的前端代码" tabindex="-1">生成的前端代码 <a class="header-anchor" href="#生成的前端代码" aria-label="Permalink to “生成的前端代码”">​</a></h3><p>按生成模式出三组模板（单表与主从共用一份，树表另一份），落在 <code>frontend/src/modules/&lt;包&gt;/views/&lt;资源&gt;/</code>：</p><table tabindex="0"><thead><tr><th>文件</th><th>写入方式</th></tr></thead><tbody><tr><td><code>index.vue</code></td><td>只首次：SchemaPage 列表页与新建 / 编辑弹窗（每个字段有可见标签），主表行展开出明细表</td></tr><tr><td><code>&lt;资源&gt;.schema.generated.ts</code></td><td>每次覆盖：字段、按钮、表单模型与缺省值、表单与请求的换算、导入换算、搜索字段到后端筛选的登记、SchemaPage 的资源</td></tr><tr><td><code>&lt;资源&gt;.schema.ts</code></td><td>只首次：在上面的 base* 之上做 transform，页面只从这里导入</td></tr></tbody></table><ul><li>取数走生成的契约客户端（<code>~/contracts</code> 的 <code>&lt;资源 camel&gt;</code>，类型取 <code>ResponseOf</code> / <code>RequestOf</code>），不生成手写的接口与类型文件；契约在后端登记之后导出、<code>pnpm gen:contracts</code> 生成。</li><li>控件由列的类型与配置单点决定（开关、日期、时间、上传、关联下拉、关联树、选项下拉、数字框、文本框），表单模型、缺省值、回填、提交与导入共用同一组判据。日期按 <code>DateTimeOffset</code> 收发；上传控件是公共组件 <code>XFileRefUpload</code>，存文件库的文件 ID。</li><li>必填在提交前校验并挂到字段上，后端的字段错误也挂回字段；按钮按权限码门控：导出用读、导入用新建、启停用修改。</li><li>文案一律写键，键在 <code>&lt;包&gt;.&lt;资源&gt;</code> 下：页面标题（也是菜单标题键）、字段名、按钮、弹窗标题、必填提示与枚举选项（选项静态写出，<code>Active</code> / <code>Disabled</code> 用固定用语，其余成员名原样）。</li><li>新建包另出 <code>setup.ts</code>（登记文案）与 <code>locales/&lt;区域&gt;.ts</code> 共 10 种区域；登记片段写明把模块名加进 <code>scripts/check-modules.mjs</code> 的 <code>KNOWN</code>，视图键 <code>&lt;资源&gt;/index</code> 要全局唯一。加入已有包时，登记片段按区域列出要合进 <code>locales</code> 的文案块。</li></ul><h2 id="生成与生成历史" tabindex="-1">生成与生成历史 <a class="header-anchor" href="#生成与生成历史" aria-label="Permalink to “生成与生成历史”">​</a></h2><table tabindex="0"><thead><tr><th>操作 / 端点</th><th>说明</th></tr></thead><tbody><tr><td><code>codegen-tables.generate</code></td><td>按表配置生成，交付方式缺省取表配置的（也可在请求里指定）；不论成败都记一条生成历史，成功才回写表的生成状态与时间</td></tr><tr><td><code>codegen-histories.list</code> / <code>get</code></td><td>生成历史：关键字匹配表名与批次号，结果可多选、生成时间按区间；详情带产物文件、用到的模板、表配置快照与失败原因</td></tr><tr><td><code>GET /api/codegen-histories/{id}/package</code></td><td>普通端点，以附件下载这次的产物包（Zip），要 <code>codegeneration.codegen-histories.read</code></td></tr></tbody></table><ul><li><strong>打包下载</strong>：每次覆盖的文件进 <code>_generated/</code>、只首次写的进 <code>_manual/</code>（各自下面再分 <code>backend/</code> 与 <code>frontend/</code>），登记片段在 <code>_registration/</code>，包根有 <code>README.txt</code>。产物包经 Files 的临时文件契约 <code>ITemporaryFiles</code>（Contracts）存成 7 天的临时文件（同导出中心），从上面的端点下载，不放进生成的响应；写进项目、生成失败或已到期的历史没有产物包（<code>CODEGENERATION_NOTFOUND_005</code>）。</li><li><strong>写进项目</strong>只在 Development、且打开 <code>BasicApp:CodeGeneration:EnableGenerateToProject</code> 时可用，其余环境 <code>CODEGENERATION_VALIDATION_010</code>。位置取配置的 <code>BackendRootPath</code>（含 <code>src/</code> 的 <code>backend</code>）与 <code>FrontendRootPath</code>（含 <code>package.json</code> 的 <code>frontend</code>），相对宿主的内容根目录、不接受表配置给的任意路径；没配或指得不对同样 <code>VALIDATION_010</code>。全部产物定好位置、都落在所属根目录之内才动磁盘。每次覆盖的直接覆盖，只首次写的已存在即跳过（响应列出跳过的文件）；只首次写的文件已在、对应的生成部分却没有，说明是项目里原有的手写文件，整体拒绝。「加入已有包」要求 <code>src/&lt;命名空间&gt;</code> 下已有这个包。登记片段写在那一侧根目录的 <code>_registration/</code>。</li><li>宿主的 <code>appsettings.Development.json</code> 打开了写盘并指向本仓库的两个工程（<code>BackendRootPath</code> 为 <code>../..</code>、<code>FrontendRootPath</code> 为 <code>../../../frontend</code>）；<code>appsettings.json</code> 里两个根目录不写，开关关着。</li><li>失败的那条历史在独立的短事务里写（调用失败会回滚自己的写入），失败原因记错误码与调用方语言的文案。</li></ul><h2 id="零代码运行时" tabindex="-1">零代码运行时 <a class="header-anchor" href="#零代码运行时" aria-label="Permalink to “零代码运行时”">​</a></h2><p>表配置的「运行时数据」按表配置只读查看表里的数据，不生成也不编译代码。</p><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><code>codegen-runtime.get-schema</code></td><td>表结构：按列配置给出列名、数据行里的键（属性名的 camelCase）、显示名（列注释）与控件</td></tr><tr><td><code>codegen-runtime.list</code></td><td>分页只读数据，每页最多 500 条；只带配置过的列，键是属性名</td></tr></tbody></table><ul><li>表名只取已配置且启用的表配置，不接受请求给的表名；停用的表配置 409 <code>CODEGENERATION_CONFLICT_007</code>。</li><li>主库里属于应用自己的表（已登记实体的表，含按月分表的日志）不读，表名带不合规字符的也不读：<code>CODEGENERATION_VALIDATION_015</code>。</li><li>按表配置的数据源读：主库的其他表补上与实体读同口径的条件（有租户列的只看调用方这一侧的行，有软删列的不看已删的）；外部库的表不是 BasicApp 的表，照原样读。</li><li>按列配置逐列取、列名照原样加引号，不取 <code>*</code>，大小写混合的表名与列名照原样查到；列配置里有、库里已没有的列读不出（503 <code>CODEGENERATION_UNAVAILABLE_003</code>，带表名与库的报错），先同步结构。数字、布尔按原类型，时间与 Guid 按文本，二进制按 Base64。PostgreSQL、MySQL、SQL Server、Oracle 在真实库上实测（<code>CodeGenerationSchemaTests</code>）。</li></ul><h2 id="退出验证" tabindex="-1">退出验证 <a class="header-anchor" href="#退出验证" aria-label="Permalink to “退出验证”">​</a></h2><p>生成的代码要跟得上各包的写法：改了 Feature、权限、页面登记、错误与消息目录、操作或 SchemaPage 的写法，要同时改内置模板（<code>Seeds/Templates/**/*.sbn</code>），再跑一次退出验证。前端产物照 lint 的换行规则出（含调用的对象一个属性一行、带嵌套的数组一项一行、含调用的三元式拆三行），前端的 lint 规则变了同样要对齐模板。它是手动触发的集成测试，不进缺省 CI：</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">XIHAN_TEST_CODEGEN_COMPILE</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">框架源码的</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 目</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">录</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  artifacts/pin/bin/XiHan.BasicApp.Integration.Tests/release/XiHan.BasicApp.Integration.Tests.exe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -class</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> XiHan.BasicApp.Integration.Tests.CodeGenerationCompileTests</span></span></code></pre></div><ul><li>变量是框架源码的 <code>src/</code> 目录（同 <code>-p:XiHanFrameworkSrc</code>），没设即跳过；前端要先在本检出的 <code>frontend</code> 装好依赖。</li><li>把当前提交的 <code>backend</code> 与 <code>frontend</code> 导出到临时目录，四张演示表各配成新建包：树表 Catalog（带生成的启停枚举）、单表 Shop（关联树、常量下拉、系统字典、图片上传、时间、布尔、日期时间与定点数）、主从 Sales / SalesItems，按「生成到项目」写进去。</li><li>照生成的登记片段登记进宿主（工程引用、<code>UseFeature</code>、OpenAPI 分组）与前端模块门禁，宿主连同四个新包 Release 构建、警告即失败；导出契约、<code>pnpm gen:contracts</code> 之后前端 <code>pnpm check</code> 十项通过。</li></ul><h2 id="模块开关" tabindex="-1">模块开关 <a class="header-anchor" href="#模块开关" aria-label="Permalink to “模块开关”">​</a></h2><p><code>BasicApp:Modules:CodeGeneration:Enabled</code> 设为 <code>false</code> 时宿主不装配 CodeGeneration：权限码与页面不下发、操作 404，产物包下载端点不映射，已登记的外部数据源连接不再建立；<code>sys_code_gen_data_source</code>、<code>sys_code_gen_table</code>、<code>sys_code_gen_table_column</code>、<code>sys_code_gen_template</code> 与 <code>sys_code_gen_history</code> 五张表仍由正式库的基线脚本建出（开发库的 <code>InitTables</code> 只建装配了的包的表）。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./development">开发流程</a> · <a href="./file">文件与存储</a> · <a href="./../configuration#basicapp-codegeneration">配置参考</a></li></ul>`,45)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};